schema:
{
  "description": "Scontrini fotografati",
  "baseAnalyzerId": "prebuilt-document",
  "config": {
    "estimateFieldSourceAndConfidence": true
  },
  "fieldSchema": {
    "fields": {
      "Data": {
        "type": "date",
        "method": "extract",
        "description": "Data in fondo allo scontrino, formato GG-MM-AAAA."
      },
      "Totale": {
        "type": "number",
        "method": "extract",
        "description": "Importo dopo \"TOTALE COMPLESSIVO\"."
      },
      "PartitaIVA": {
        "type": "string",
        "method": "extract",
        "description": "Partita IVA dell'esercente, sotto l'indirizzo."
      }
    }
  }
}
